import argparse
import sys


def transform(text, upper=False, reverse=False):
    """Apply the requested transformations to *text*."""
    if upper:
        text = text.upper()
    if reverse:
        text = text[::-1]
    return text


def build_parser():
    parser = argparse.ArgumentParser(
        prog="tool.py", description="Transform text arguments."
    )
    parser.add_argument("--upper", action="store_true", help="uppercase the text")
    parser.add_argument("--reverse", action="store_true", help="reverse the text")
    parser.add_argument("text", nargs="*", metavar="TEXT", help="text to transform")
    return parser


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)
    if not args.text:
        parser.error("the following arguments are required: TEXT")
    joined = " ".join(args.text)
    result = transform(joined, upper=args.upper, reverse=args.reverse)
    print(result)
    return 0


if __name__ == "__main__":
    sys.exit(main())
